  help_a_logging: "سجّلي من شاشتك الرئيسية أو من تبويب التقويم — اختاري اليوم وما تريدين تدوينه: الدورة، الأعراض، المزاج، النوم وغيرها. يظهر كل شيء في تقويمك وفي ملاحظاتك.",
