  help_a_export: "اذهبي إلى الإعدادات ← البيانات والخصوصية ← البيانات التي نحتفظ بها ← تصدير كل بياناتي. ستحصلين على نسخة JSON كاملة قابلة للقراءة آلياً لكل ما نخزّنه.",
  help_q_delete: "كيف أحذف حسابي؟",
  help_a_delete: "الإعدادات ← الحساب ← حذف الحساب. يمحو هذا بياناتكِ نهائياً من أنظمتنا ولا يمكن التراجع عنه.",
  help_q_password: "كيف أغيّر كلمة المرور؟",
  help_a_password: "الإعدادات ← الحساب ← تغيير كلمة المرور. إذا سجّلتِ الدخول عبر Apple أو Google، فأدِيري تسجيل دخولكِ من خلال ذلك المزوّد.",
  help_q_invite: "كيف أدعو دائرة الرعاية؟",
  help_a_invite: "الإعدادات ← دائرة الرعاية ← دعوة. أرسلي رابطاً آمناً إلى الشريك أو المربية أو أحد الأجداد. ينضمّون بالصلاحيات التي تختارينها بالضبط.",
  help_q_permissions: "هل أتحكّم فيما يراه مقدّمو الرعاية؟",
  help_a_permissions: "نعم. لكل مُقدّم رعاية صلاحيات تحدّدينها — أنتِ من يقرّر من يمكنه عرض السجلات أو إضافتها والسجلات الصحية وغيرها. غيّري الوصول أو ألغيه في أي وقت.",
  help_q_grandma: "من هي Grandma؟",
  help_a_grandma: "Grandma رفيقتكِ بالذكاء الاصطناعي، مدعومة بـ Claude. تجيب عن أسئلتكِ بسياق رحلتكِ وتقدّم إرشادات دافئة وعملية ليلاً ونهاراً.",
  help_q_medical: "هل نصيحة Grandma نصيحة طبية؟",
  help_a_medical: "لا. تقدّم Grandma إرشاداً حنوناً وتثقيفياً — لا تشخيصاً ولا علاجاً. استشيري دائماً طبيبكِ أو قابلتكِ أو طبيب الأطفال في الأمور الطبية.",
  help_q_premium: "ماذا تشمل Premium؟",
  help_a_premium: "تفتح Premium المسح والمحادثة دون حدود، والرؤى الكاملة، والتذكيرات. يمكنكِ الاشتراك شهرياً أو سنوياً.",
  help_q_cancel: "كيف ألغي Premium؟",
  help_a_cancel: "أدِيري اشتراككِ أو ألغيه في أي وقت من إعدادات حسابكِ في متجر التطبيقات. تبقى ميزات Premium فعّالة حتى نهاية فترة الفوترة.",
  help_q_dataSafe: "هل بياناتي آمنة؟",
  help_a_dataSafe: "نعم. بياناتكِ مشفّرة أثناء النقل والتخزين، ومحمية بأمان على مستوى الصفوف بحيث لا يصل إليها إلا أنتِ ودائرة الرعاية التي تختارينها.",
  help_q_sell: "هل تبيعون بياناتي؟",
  help_a_sell: "أبداً. لا نبيع بياناتكِ الشخصية، ولا نستخدم بياناتكِ الصحية أو بيانات أطفالكِ الخاصة لتدريب ذكاء اصطناعي تابع لجهة خارجية.",
