  guidelines_subtitle: "مكان لطيف للمشاركة",
  guidelines_intro: "grandma.app مساحة يدعم فيها الآباء والأمهات بعضهم بصدق. ولنُبقيها آمنة للجميع، نرجو منكِ اتباع بضع قواعد بسيطة.",
  guidelines_rule1Title: "كوني لطيفة ومحترمة",
  guidelines_rule1Body: "كل واحدة هنا في رحلتها الخاصة. لا مضايقة ولا تنمّر ولا خطاب كراهية ولا هجوم شخصي.",
  guidelines_rule2Title: "احمي الخصوصية",
  guidelines_rule2Body: "لا تشاركي معلومات الآخرين الشخصية أو الصحية. وفكّري جيداً فيما تكشفينه عن عائلتكِ أيضاً.",
  guidelines_rule3Title: "شاركي الدعم، لا التشخيص",
  guidelines_rule3Body: "قدّمي التجربة والتشجيع — لا التوجيهات الطبية. وفي الأمور الطبية، وجّهي الناس دائماً إلى طبيبهم.",
  guidelines_rule4Title: "لا بريد مزعج ولا بيع",
  guidelines_rule4Body: "أبقي المجتمع للتواصل لا للترويج. إعلانات السوق مكانها التبادل، لا الصفحة الرئيسية.",
  guidelines_rule5Title: "حافظي على الأمان",
  guidelines_rule5Body: "لا محتوى يشجّع على إيذاء النفس أو تعريض الأطفال للخطر أو أي أمر غير قانوني. نزيله وقد نوقف الحساب.",
  guidelines_sectionReport: "إذا رأيتِ شيئاً",
  guidelines_reportBody: "اضغطي مطولاً على أي منشور أو رسالة للإبلاغ عنه أو حظر الشخص. البلاغات خاصة ويراجعها فريقنا. وفي حالة الطوارئ، تواصلي دائماً مع خدمات الطوارئ المحلية.",
  guidelines_footer: "قد يؤدي خرق هذه القواعد إلى إزالة المحتوى أو إيقاف الحساب. شكراً لحفاظكِ على أمان هذا المجتمع.",
