  sw1_pp_oBreech: "مقعدي",
  sw1_pp_oTransverse: "عرضي",
  sw2_leap19_name: "الأحداث",
  sw2_leap19_desc: "فهم أن الأفعال تحدث بالتسلسل",
  sw2_leap19_brain: "في هذه المرحلة يبدأ الأطفال غالبًا برؤية العالم كسلسلة من الأحداث بدل أن يكون مشهدًا واحدًا غير واضح. للأفعال بداية ووسط ونهاية. هذه بداية التفكير بالسبب والنتيجة، ولهذا قد يبدو كل شيء مثيرًا فجأة.",
  sw2_leap19_tip: "العبوا ألعاب السبب والنتيجة البسيطة مثل «بيكابو» — فالطفل يتعلم أن للأحداث نتائج يمكن توقعها.",
  sw2_leap19_ph0: "التصاق شديد، بكاء عند وضعه، واضطراب في النوم. قد يشعر الطفل بالتعب لأن أشياء كثيرة جديدة تحدث دفعة واحدة.",
  sw2_leap19_ph1: "غالبًا ما ينشغل الطفل بربط كل فعل بما يحدث بعده — يدفع ويُسقط ويراقب عن كثب.",
  sw2_leap19_ph2: "تظهر حركة الوصول المقصودة مع بدايات إدراك بقاء الأشياء — يبحث الطفل عمّا سقط منه.",
  sw2_leap19_sg0: "زيادة قلق الانفصال",
  sw2_leap19_sg1: "شديد التعلق",
  sw2_leap19_sg2: "يبكي عند سقوط لعبة",
  sw2_leap19_sg3: "يقاوم القيلولة",
  sw2_leap19_sg4: "يطلب التفاعل باستمرار",
  sw2_leap19_sg5: "ينزعج عندما يتغير الروتين",
  sw2_leap19_sk0: "يمدّ يده ويمسك عن قصد",
  sw2_leap19_sk1: "يهزّ الألعاب ويضربها",
  sw2_leap19_sk2: "يتعرف على الألعاب",
  sw2_leap19_sk3: "يفهم «فوق» و«تحت»",
  sw2_leap19_sk4: "يتابع الأشياء المتحركة بعينيه",
  sw2_leap19_sk5: "يضحك للمفاجآت",
  sw2_leap19_ac0: "لعبة «بيكابو» والاختباء",
  sw2_leap19_ac1: "تدحرج كرة ذهابًا وإيابًا",
  sw2_leap19_ac2: "ألعاب بسيطة للسبب والنتيجة (اضغط = صوت)",
  sw2_leap19_ac3: "اروِ الروتين اليومي خطوة بخطوة",
  sw2_leap5_name: "حواس متغيّرة",
  sw2_leap5_desc: "يكتشف الرضيع عالمًا أغنى من الحواس",
  sw2_leap5_brain: "في هذه الفترة قد يبدأ طفلك بالتقاط تفاصيل أكثر بكثير عبر حواسه: مشاهد أوضح، وأصوات أغنى، وأحاسيس جديدة في جسده. قد يبدو الأمر كثيرًا، ورائعًا في الوقت نفسه.",
  sw2_leap5_ph0: "من الشائع أن يزداد البكاء والتعلّق وأن يضطرب النوم. قد يكون الطفل يستقبل الكثير من المعلومات الحسية الجديدة.",
  sw2_leap5_ph1: "يستوعب الطفل الكثير من المشاهد والأصوات الجديدة. قد يبلغ التذمّر ذروته ثم يهدأ.",
  sw2_leap5_ph2: "يزدهر الوعي الحسي الجديد، وستلاحظ فترات يقظة أطول ونظرات أكثر تعمّدًا.",
  sw2_leap5_sg0: "يبكي أكثر من المعتاد",
