  sw2_leap12_name: "انتقالات سلسة",
  sw2_leap12_desc: "تصبح الحركات والتحكم بالعضلات أكثر سلاسة",
  sw2_leap12_brain: "في هذه الفترة قد تبدو حركات طفلك أكثر سلاسة وتناسقًا. تتراجع الانعكاسات المتقطعة تدريجيًا لتحلّ محلها حركات أكثر قصدًا، وقد يصبح أكثر وعيًا بجسده.",
  sw2_leap12_ph0: "قد يظهر نوم مضطرب وطلبات أكثر ورضاعة أكثر بينما يبذل الطفل طاقته في الحركات الجديدة.",
  sw2_leap12_ph1: "الطفل منشغل بتمرين حركات جديدة وقد يبدو قلقًا أو منزعجًا من الأحاسيس الجسدية الجديدة.",
  sw2_leap12_ph2: "تظهر حركات أكثر سلاسة وابتسامات اجتماعية وأولى الضحكات الحقيقية مع استقرار التحكم الجسدي الجديد.",
  sw2_leap12_sg0: "نوم مضطرب",
  sw2_leap12_sg1: "تذمّر أكثر",
  sw2_leap12_sg2: "رضعات أكثر",
  sw2_leap12_sg3: "يريد محفزات بصرية",
  sw2_leap12_sg4: "لا يحب السكون",
  sw2_leap12_sg5: "يكرّر الحركات للتمرّن",
  sw2_leap12_sk0: "تحكّم ثابت بالرأس",
  sw2_leap12_sk1: "يضم يديه إلى منتصف جسمه",
  sw2_leap12_sk2: "أولى الضحكات الحقيقية",
  sw2_leap12_sk3: "يمسك الأشياء لوقت قصير",
  sw2_leap12_sk4: "يركل بساقيه بإيقاع",
  sw2_leap12_sk5: "يُدخل يديه إلى فمه عن قصد",
  sw2_leap12_ac0: "وقت الاستلقاء على البطن يوميًا في جلسات من 3 إلى 5 دقائق",
  sw2_leap12_ac1: "دعه يضرب الألعاب المعلّقة",
  sw2_leap12_ac2: "جلوس مع دعم للظهر",
  sw2_leap12_ac3: "حرّك ذراعي الطفل وساقيه كحركة الدراجة",
  sw2_leap12_tip: "وقت البطن اليومي (جلسات من 3 إلى 5 دقائق) قد يدعم مهارات الحركة التي تظهر الآن.",
  sw2_leap37_name: "الفئات",
  sw2_leap37_desc: "تصنيف العالم في فئات",
  sw2_leap37_brain: "في هذه المرحلة يبدأ الأطفال غالبًا بتصنيف العالم في مجموعات، مثل الحيوانات والأطعمة والناس والألوان. يدعم هذا التصنيف اللغة والتفكير لاحقًا. وغالبًا ما تظهر الكلمات الأولى في هذه الفترة أو بعدها بقليل.",
  sw2_leap37_tip: "سمِّ كل شيء — «كرة كبيرة، كرة صغيرة». قد تفيد ألعاب الفرز والكتب ذات الفئات الواضحة في هذه المرحلة.",
  sw2_leap37_ph0: "قد تظهر المطالب الكثيرة والانتقائية في الطعام والاستيقاظ الليلي بينما يبدأ الطفل بتصنيف العالم.",
  sw2_leap37_ph1: "غالبًا ما ينشغل الطفل بتصنيف تجاربه في مجموعات. وقد يبدو أكثر انتقائية وتمسكًا برأيه.",
  sw2_leap37_ph2: "يفرز الطفل الأشياء حسب النوع ويشير إلى أجزاء الجسم وقد ينطق أولى كلماته المفهومة.",
  sw2_leap37_sg0: "تعود الانتقائية في الطعام",
  sw2_leap37_sg1: "أكثر مطالبة",
  sw2_leap37_sg2: "شديد التعلق بمقدّم الرعاية الأساسي",
