  sw2_an_sleepTitle: "النوم هذا الأسبوع",
  sw2_an_sleepBody: "المتوسط {{avg}} ساعة يوميًا — والمرجع المعتاد في هذا العمر حوالي {{target}} ساعة.",
  sw2_an_sleepDetail: "في الأيام التي سجّلتها، نام {{name}} بمتوسط {{avg}} ساعة يوميًا. في عمر {{months}} شهرًا يكون المرجع المعتاد حوالي {{target}} ساعة يوميًا شاملة القيلولات.",
  sw2_an_sleepGood: "تم تسجيل {{good}} من أصل {{total}} فترات نوم على أنها جيدة أو ممتازة.",
  sw2_an_sleepHint: "قد يساعد النوم مبكرًا قليلًا وخفض الإضاءة قبل النوم بـ 30 دقيقة وروتين هادئ ثابت.",
  sw2_an_sleepStartTitle: "ابدأ بتسجيل النوم",
  sw2_an_sleepStartBody: "سجّل النوم لترى ساعات {{name}} اليومية بجانب المرجع المعتاد {{target}} ساعة.",
  sw2_an_sleepStartDetail: "في عمر {{months}} شهرًا يكون المرجع المعتاد حوالي {{target}} ساعة نوم يوميًا شاملة القيلولات. سجّل كل نوم في التقويم ← النوم.",
  sw2_an_feedsTitle: "الرضعات هذا الأسبوع",
  sw2_an_mealsTitle: "الوجبات هذا الأسبوع",
  sw2_an_feedsBody: "الرضعات المسجّلة: {{n}}، حوالي {{avg}} يوميًا.",
  sw2_an_mealsBody: "الوجبات المسجّلة: {{n}}، حوالي {{avg}} يوميًا.",
  sw2_an_mealsBodyAte: "الوجبات المسجّلة: {{n}}، حوالي {{avg}} يوميًا؛ {{pct}}% منها مسجّلة «أكل جيدًا».",
  sw2_an_tryNew: "جرّب هذا الأسبوع طعامًا أو اثنين جديدين.",
  sw2_an_feedsDetail: "في الأيام التي سجّلتها، تناول {{name}} حوالي {{avg}} رضعات يوميًا. تسجيل كل رضعة يجعل الصورة أوضح.",
  sw2_an_mealsDetail: "في الأيام التي سجّلتها، تناول {{name}} حوالي {{avg}} وجبات يوميًا، و{{pct}}% منها مسجّلة «أكل جيدًا». غالبًا ما يحتاج الطفل إلى 10–15 محاولة لقبول طعام جديد — قدّمه بجانب أطعمة مألوفة وفي مواعيد ثابتة.",
  sw2_an_moodsTitle: "المزاج هذا الأسبوع",
  sw2_an_moodsBody: "المزاج المسجّل: {{n}} — «{{top}}» الأكثر ظهورًا؛ {{fussy}} غاضب أو متذمّر.",
  sw2_an_moodsDetailFussy: "كان المزاج الأكثر تسجيلًا لدى {{name}} هو «{{top}}»، وسُجّل {{fussy}} من أصل {{total}} على أنه غاضب أو متذمّر. كثيرًا ما تأتي فترات التذمّر مع التسنين (شائع بين 6 و24 شهرًا) أو طفرات النمو أو قلة النوم أو تغيّر الروتين. قد يساعد مزيد من الاحتضان وروتين ثابت — وإن كنت قلقًا فتحدّث مع طبيب الأطفال.",
  sw2_an_moodsDetailCalm: "كان المزاج الأكثر تسجيلًا لدى {{name}} هو «{{top}}» دون تسجيل أي مزاج غاضب أو متذمّر. غالبًا ما يسير الروتين الثابت والنوم الكافي جنبًا إلى جنب مع الأيام الهادئة.",
  sw2_an_actTitle: "مرجع النشاط اليومي",
  sw2_an_actBody: "المرجع المعتاد: {{target}} يوميًا لعمر {{age}}.",
  sw2_an_actTargetTummy: "20–30 دقيقة على البطن",
  sw2_an_actTargetPlay: "60 دقيقة لعب نشط",
  sw2_an_actDetailBaby: "وقت البطن يقوّي الرقبة والكتفين والجذع للتقلّب والجلوس والزحف. ابدأ بجلسات من 2–3 دقائق وزد تدريجيًا إلى 20–30 دقيقة موزعة على اليوم. استلقِ على الأرض معه ليصبح الأمر ممتعًا.",
  sw2_an_actDetailToddler: "اللعب النشط يدعم مهارات الحركة والنوم والمزاج. واللعب في الخارج يضيف ضوء النهار والهواء النقي وكثيرًا لاستكشافه. حتى 3 جلسات مدة كل منها 20 دقيقة تُحتسب.",
  sw2_an_growthTitle: "سجّل النمو",
  sw2_an_growthBody: "سجّل وزن {{name}} وطوله لتراهما عبر الزمن.",
  sw2_an_growthDetail: "يصبح مخطط النمو أكثر فائدة مع كل قياس. سجّل الوزن والطول ومحيط الرأس بعد كل زيارة لطبيب الأطفال في التقويم ← النمو.",
  sw2_an_diaperTitle: "الحفاضات هذا الأسبوع",
  sw2_an_diaperLowBody: "المتوسط {{avg}} حفاضات يوميًا — والمرجع الشائع للرضّع الصغار 6 حفاضات مبلّلة أو أكثر يوميًا.",
  sw2_an_diaperLowDetail: "استخدم {{name}} في آخر {{days}} أيام بمتوسط {{avg}} حفاضات يوميًا. المرجع الشائع للرضّع دون 6 أشهر هو 6 حفاضات مبلّلة أو أكثر يوميًا. إن لم تكن متأكدًا من الرضاعة فاتصل بطبيب الأطفال.",
  sw2_an_diaperGreenBody: "تم تسجيل {{n}} حفاضات خضراء هذا الأسبوع.",
  sw2_an_diaperGreenDetail: "البراز الأخضر شائع مع تغيّر النظام الغذائي أو مكملات الحديد. وإن جاء مع تذمّر أو أي شيء آخر يقلقك فتحدّث مع طبيب الأطفال.",
  sw2_an_diaperTrackTitle: "سجّل الحفاضات",
  sw2_an_diaperTrackBody: "سجّل تغييرات حفاضات {{name}} لترى الأنماط اليومية.",
  sw2_an_diaperTrackDetail: "تعرض سجلات الحفاضات الأنماط اليومية بنظرة واحدة — العدد ومبلّل أو متّسخ والألوان. سجّل كل تغيير في التقويم ← الحفاض.",
  sw2_an_cntNutBreast: "يحسب الرضاعة الطبيعية والزجاجة وكيف كانت كل واحدة (أكل جيدًا / قليلًا / لم يأكل).",
  sw2_an_cntNutMeals: "يحسب الوجبات والرضعات وكيف كانت كل واحدة (أكل جيدًا / قليلًا / لم يأكل).",
